afterExample:
import org.eclipse.swt.widgets.Control;

class SuperClass {
    public void install(Control subjectControl) {}
}

public class MyClass extends SuperClass {
    /**
     * {@inheritDoc}
     */
    @Override
    public void install(Control subjectControl) {
        super.install(subjectControl);
    }

    public void nonOverriddenMethod() {}
}

negativeExample:
import org.eclipse.swt.widgets.Control;

public class MyClass {
    // This method does not override anything, so @Override should not be added.
    public void nonOverriddenMethod() {
        System.out.println("Hello");
    }

    // This method already has @Override, so it should not be changed.
    @Override
    public String toString() {
        return super.toString();
    }
}
